<script setup>
import { computed } from 'vue';
import { Eye, Layers3, LayoutDashboard, Users, CreditCard, BarChart3, Settings2, Search, Plus, ChevronDown, X, Check, CheckCircle2, Clock3, Sparkles, ShieldCheck, Bell, Download, MoreHorizontal, Menu, Gift, History, SlidersHorizontal, CircleHelp, RefreshCw, Moon, Sun, Home } from '@lucide/vue';
import AppSelect from '../../shared/AppSelect.vue';
import UserSearchSelect from '../../shared/UserSearchSelect.vue';
import { theme, toggleTheme } from '../appearance/theme';
import { useAdminPanel } from './useAdminPanel';
const nav=[{id:'overview',label:'Visão geral',icon:LayoutDashboard},{id:'users',label:'Usuários',icon:Users},{id:'subscriptions',label:'Assinaturas',icon:CreditCard},{id:'activity',label:'Histórico de ações',icon:History},{id:'settings',label:'Configurações',icon:Settings2}];
const {view,search,statusFilter,originFilter,page,sidebar,period,modal,selected,toast,queryInput,formError,submitting,error,loading,listLoading,ready,counts,revenue,recentUsers,rows,settings,draft,billingConfig,resultTotal,totalPages,eventPage,eventPages,eventTotal,grantTargets,recipientLoading,recipientError,recipientTotal,form,actionReason,events,currentAdmin,money,date,dateFull,dateTime,initials,labels,charts,chartMax,chartLabels,line,periodLabel,asOf,minGrantDate,grantTimezone,notify,go,refresh,searchRecipients,openGrant,close,openDetails,grant,requestRevoke,revoke,toggleAccount,confirmAccount,saveSettings,discardSettings,exportCsv,focusSearch}=useAdminPanel();
const title=computed(()=>nav.find(item=>item.id===view.value)?.label||'Administração');
</script>


<template>
<div class="admin-shell">
 <div v-if="sidebar" class="mobile-scrim" @click="sidebar=false"></div>
 <aside class="sidebar" :class="{open:sidebar}">
  <a href="#" class="brand" @click.prevent="go('overview')"><span class="brand-symbol"><Layers3 :size="24"/></span>{{settings.name}}<span class="brand-dot">.</span></a>
  <a class="admin-exit-link" href="/"><Home :size="17"/> Voltar ao Tempozi</a><div class="workspace-mark"><span class="workspace-icon"><ShieldCheck :size="18"/></span><div><strong>Central de controle</strong><small>Workspace do administrador</small></div><ChevronDown :size="14"/></div>
  <div class="nav-label">PRINCIPAL</div>
  <nav><button v-for="item in nav" :key="item.id" :class="{active:view===item.id}" @click="go(item.id)"><component :is="item.icon" :size="18"/><span>{{item.label}}</span><span v-if="item.id==='subscriptions'" class="nav-badge">{{counts.active}}</span></button></nav>
  <div class="sidebar-note"><div class="note-orbit"><Sparkles :size="20"/></div><strong>Controle com cuidado.</strong><p>Cada acesso é uma pessoa construindo algo com o Tempozi.</p><button @click="modal='help'">Conhecer o painel </button></div>
  <div class="sidebar-bottom"><span class="live-dot"></span> Administração protegida <button aria-label="Ajuda da administração" @click="modal='help'"><CircleHelp :size="15"/></button></div>
  <button class="admin-account" @click="go('settings')"><span class="avatar owner">{{initials(currentAdmin.name)}}</span><span><strong>{{currentAdmin.name}}</strong><small>Administrador</small></span><Settings2 :size="16"/></button>
 </aside>
 <div class="main-shell">
  <header class="topbar"><div class="breadcrumbs"><button class="icon-button mobile-menu" aria-label="Abrir menu" @click="sidebar=true"><Menu :size="20"/></button><span>Administração</span><strong>{{title}}</strong></div><div class="header-actions"><button class="search-shortcut" @click="focusSearch"><Search :size="16"/><span>Buscar usuário</span><kbd>Ctrl K</kbd></button><button class="icon-button theme-toggle" type="button" role="switch" :aria-checked="theme==='graphite'" :aria-label="theme==='graphite'?'Trocar para tema claro':'Ativar tema escuro Grafite'" :title="theme==='graphite'?'Tema Grafite':'Tema claro'" @click="toggleTheme"><Moon v-if="theme==='graphite'" :size="17"/><Sun v-else :size="17"/></button><button class="icon-button notification-button" aria-label="Ver alertas" @click="modal='notifications'"><Bell :size="18"/><i v-if="counts.pending>0"></i></button><span class="avatar owner small">{{initials(currentAdmin.name)}}</span></div></header>
  <main>
   <div class="demo-strip"><span><ShieldCheck :size="13"/> ADMINISTRAÇÃO</span><p v-if="asOf">Atualizado em {{dateTime(asOf)}}</p><button :disabled="loading" @click="refresh"><RefreshCw :size="13" :class="{spin:loading}"/> {{loading?'Atualizando…':'Atualizar dados'}}</button><a href="/" class="button admin-return-link"><Home :size="15"/> Voltar ao Tempozi </a></div><div v-if="error" class="admin-error" role="alert">{{error}}<button class="button" :disabled="loading" @click="refresh">Tentar novamente</button></div><p v-if="!ready&&!error" class="admin-load-status" role="status">Carregando dados administrativos…</p>
   <Transition name="page" mode="out-in"><div v-if="ready" :key="view">
    <section class="page-heading"><div><div class="eyebrow">{{view==='overview'?'SEU NEGÓCIO, EM PERSPECTIVA':'CENTRAL DE CONTROLE'}}</div><h1>{{view==='overview'?'Tudo flui por aqui.':title}}<span v-if="view==='overview'" class="title-spark">✳</span></h1><p>{{view==='overview'?'Acompanhe seu crescimento e cuide de quem faz parte do Tempozi.':view==='users'?'Pessoas, acessos e o próximo passo de cada conta.':view==='subscriptions'?'Receita e benefícios, com clareza em cada assinatura.':view==='activity'?'Um registro de cada decisão tomada na administração.':'Deixe o Tempozi do seu jeito, com tudo sob controle.'}}</p></div><div class="heading-actions"><AppSelect v-if="view==='overview'" class="admin-period-select" aria-label="Período do gráfico" v-model="period" :options='[{"label":"Últimos 30 dias","value":"month"},{"label":"Últimos 7 dias","value":"week"}]'><template #icon><Clock3 :size="15"/></template></AppSelect><button v-if="view!=='settings'&&view!=='activity'" class="button primary" @click="openGrant()"><Plus :size="16"/> Conceder acesso Pro</button></div></section>
    <template v-if="view==='overview'">
     <section class="welcome-banner"><div class="welcome-copy"><span class="pill pale"><span class="live-dot"></span> UM BOM MOMENTO PARA CRESCER</span><h2>Mais pessoas.<br>Mais ideias em movimento.</h2><p>{{counts.active}} pessoas têm acesso ao Pro. Continue acompanhando o que faz seu produto crescer.</p><button class="text-link" @click="go('users')">Conhecer meus usuários </button></div><div class="hero-art"><img src="/ui/admin-growth.png" alt="Arcos de vidro verde, plantas e degraus de cerâmica, simbolizando crescimento."/></div><span class="art-caption"><Sparkles :size="12"/> Espaço para crescer</span></section>
     <section class="metric-grid">
      <button class="metric-card" @click="go('users')"><div class="metric-top">Total de usuários <span class="metric-icon sage"><Users :size="18"/></span></div><div class="metric-value">{{counts.total}}<span v-if="counts.new>0" class="trend" title="Novos usuários no período"> +{{counts.new}}</span></div><div class="metric-foot">pessoas no seu workspace </div></button>
      <button class="metric-card" @click="go('subscriptions','active')"><div class="metric-top">Acessos Pro ativos <span class="metric-icon purple"><CreditCard :size="18"/></span></div><div class="metric-value">{{counts.active}}<span class="metric-tag">{{Math.round(counts.active/Math.max(1,counts.total)*100)}}% da base</span></div><div class="metric-foot">{{counts.paid}} pagas · {{counts.manual}} cortesias </div><div class="mini-progress"><i :style="{width:counts.paid/Math.max(1,counts.total)*100+'%'}"></i><b :style="{width:counts.manual/Math.max(1,counts.total)*100+'%'}"></b></div></button>
      <button class="metric-card revenue-card" @click="go('subscriptions');originFilter='paid'"><div class="metric-top">Receita mensal estimada <span class="metric-icon sage"><BarChart3 :size="18"/></span></div><div class="metric-value currency">{{money(revenue)}}</div><div class="metric-foot"><span><span class="live-dot"></span> Acessos Pro ativos · estimativa</span></div><div class="metric-subtle">Não representa pagamentos recebidos.</div></button>
      <button class="metric-card" @click="go('subscriptions','canceled')"><div class="metric-top">Acessos encerrados <span class="metric-icon peach"><X :size="18"/></span></div><div class="metric-value">{{counts.canceled}}<span class="metric-tag neutral">histórico</span></div><div class="metric-foot">Acompanhar e reconectar </div><div class="metric-subtle">Oportunidades para um novo começo.</div></button>
     </section>
     <div class="analytics-grid">
      <section class="panel growth-panel"><div class="panel-title"><div><h3>O ritmo do seu crescimento</h3><p>Novos usuários por dia · {{grantTimezone}}</p></div><span class="pill sage"><span class="live-dot"></span> {{periodLabel}}</span></div><div class="chart-head"><strong>{{counts.new}}</strong><span class="legend"><i></i> Cadastros</span></div><div class="line-chart"><div class="y-axis"><span>{{chartMax}}</span><span>{{Math.round(chartMax*2/3)}}</span><span>{{Math.round(chartMax/3)}}</span><span>0</span></div><div class="plot"><div class="chart-grid"></div><svg viewBox="0 0 600 160" preserveAspectRatio="none" role="img" aria-label="Cadastros reais no período selecionado"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="var(--theme-chart-regular)" stop-opacity=".24"/><stop offset="100%" stop-color="var(--theme-chart-regular)" stop-opacity="0"/></linearGradient></defs><polygon :points="'0,160 '+line+' 600,160'" fill="url(#area)"/><polyline class="chart-line" :points="line" fill="none" stroke="var(--theme-chart-regular)" stroke-width="2.8" vector-effect="non-scaling-stroke"/><circle cx="600" :cy="150-(charts.at(-1)||0)/chartMax*140" r="4" fill="var(--theme-chart-regular)" stroke="var(--theme-panel)" stroke-width="2"/></svg><div class="x-axis"><span v-for="label in chartLabels" :key="label">{{label}}</span></div></div></div><div class="chart-footer"><span> Uma visão simples para decisões melhores.</span><button class="text-link" @click="go('subscriptions')">Ver assinaturas </button></div></section>
      <section class="panel distribution-panel"><div class="panel-title"><div><h3>Cada acesso conta</h3><p>Distribuição da sua base</p></div><Users :size="17"/></div><div class="donut-wrap"><div class="donut" :style="{background:'conic-gradient(var(--theme-chart-regular) 0 '+counts.paid/Math.max(1,counts.total)*100+'%, var(--theme-chart-extra) '+counts.paid/Math.max(1,counts.total)*100+'% '+counts.active/Math.max(1,counts.total)*100+'%, var(--theme-line) '+counts.active/Math.max(1,counts.total)*100+'% 100%)'}"><div><strong>{{counts.total}}</strong><span>usuários</span></div></div><span class="donut-spark">✳</span></div><div class="distribution-row"><span><i style="background:var(--theme-chart-regular)"></i> Pro pago</span><strong>{{counts.paid}}</strong><span>{{Math.round(counts.paid/Math.max(1,counts.total)*100)}}%</span></div><div class="distribution-row"><span><i style="background:var(--theme-chart-extra)"></i> Pro cortesia</span><strong>{{counts.manual}}</strong><span>{{Math.round(counts.manual/Math.max(1,counts.total)*100)}}%</span></div><div class="distribution-row"><span><i style="background:var(--theme-line)"></i> Sem Pro ativo</span><strong>{{counts.total-counts.active}}</strong><span>{{Math.round((counts.total-counts.active)/Math.max(1,counts.total)*100)}}%</span></div></section>
     </div>
     <div v-if="counts.pending>0" class="attention-strip"><span class="attention-icon"><Clock3 :size="18"/></span><div><strong>{{counts.pending}} pagamentos precisam de atenção</strong><p>Uma nova tentativa pode ajudar seus usuários a continuar no Tempozi.</p></div><button class="text-link" @click="go('subscriptions','past_due')">Acompanhar pagamentos </button></div>
     <div class="lower-grid"><section class="panel"><div class="panel-title"><div><h3>Pessoas por trás dos números</h3><p>Uma amostra dos usuários da sua base</p></div><button class="text-link" @click="go('users')">Ver todos </button></div><div class="table-wrap" :aria-busy="listLoading"><table><thead><tr><th>USUÁRIO</th><th>PLANO / SITUAÇÃO</th><th>ACESSO</th></tr></thead><tbody><tr v-for="user in recentUsers" :key="user.id"><td><button class="user-cell user-link" @click="openDetails(user)"><span class="avatar" :class="'color-'+user.id%4">{{initials(user.name)}}</span><span><strong>{{user.name}}</strong><small>{{user.email}}</small></span></button></td><td><span class="status-badge" :class="user.status"><i></i>{{labels[user.status] || user.status}}</span></td><td><button class="icon-button" :aria-label="'Ver '+user.name" @click="openDetails(user)"><Eye :size="16"/></button></td></tr></tbody></table></div></section>
     <section class="panel timeline-panel"><div class="panel-title"><div><h3>Ações administrativas recentes</h3><p>Os últimos registros da administração</p></div><span class="tiny-dot"></span></div><div class="timeline"><div v-for="event in events.slice(0,3)" :key="event.id" class="timeline-item"><span class="timeline-icon" :class="event.type"><Gift v-if="event.type==='grant'" :size="15"/><CreditCard v-else-if="event.type==='subscription'" :size="15"/><Clock3 v-else :size="15"/></span><div><strong>{{event.title}}</strong><p>{{event.detail}}</p><small v-if="event.expires_at">Validade: {{dateTime(event.expires_at)}}</small><small>{{dateTime(event.time)}} · {{event.actor}}</small></div></div></div><button class="timeline-more" @click="go('activity')">Abrir histórico completo </button></section></div>
    </template>


    <template v-else-if="view==='users'||view==='subscriptions'">
     <div class="summary-pills"><button :class="{selected:statusFilter==='all'}" @click="statusFilter='all'">Todos <b>{{view==='users'?counts.total:counts.subscribed}}</b></button><button :class="{selected:statusFilter==='active'}" @click="statusFilter='active'"><i class="dot-green"></i> Ativas <b>{{counts.active}}</b></button><button :class="{selected:statusFilter==='manual'}" @click="statusFilter='manual'">Cortesias <b>{{counts.manual}}</b></button><button :class="{selected:statusFilter==='past_due'}" @click="statusFilter='past_due'">Pendentes <b>{{counts.pending}}</b></button><button :class="{selected:statusFilter==='canceled'}" @click="statusFilter='canceled'">Canceladas <b>{{counts.canceled}}</b></button><button v-if="view==='users'" :class="{selected:statusFilter==='free'}" @click="statusFilter='free'">Sem histórico <b>{{counts.free}}</b></button><button v-if="view==='users'" :class="{selected:statusFilter==='disabled'}" @click="statusFilter='disabled'">Contas desativadas <b>{{counts.disabled}}</b></button></div>
     <section class="panel directory"><div class="directory-tools"><label class="search-field"><Search :size="17"/><input ref="queryInput" v-model="search" placeholder="Buscar por nome ou e-mail" aria-label="Buscar por nome ou e-mail"/><button v-if="search" aria-label="Limpar busca" @click="search=''"><X :size="14"/></button></label><div class="table-actions"><AppSelect class="admin-origin-select" aria-label="Filtrar origem" v-model="originFilter" :options='[{"label":"Todas as origens","value":"all"},{"label":"Pagamento Stripe","value":"paid"},{"label":"Concessão manual","value":"manual"}]'><template #icon><SlidersHorizontal :size="15"/></template></AppSelect><button class="button" @click="exportCsv"><Download :size="15"/> Exportar CSV</button></div></div>
      <div class="table-wrap" :aria-busy="listLoading"><table><thead><tr><th>USUÁRIO</th><th>PLANO / SITUAÇÃO</th><th>ORIGEM</th><th>{{view==='subscriptions'?'FIM DO ACESSO':'CADASTRO'}}</th><th>BENEFÍCIO</th><th></th></tr></thead><tbody><tr v-for="user in rows" :key="user.id"><td><button class="user-cell user-link" @click="openDetails(user)"><span class="avatar" :class="'color-'+user.id%4">{{initials(user.name)}}</span><span><strong>{{user.name}}<span v-if="user.disabled" class="disabled-tag">desativada</span></strong><small>{{user.email}}</small></span></button></td><td><span class="status-badge" :class="user.status"><i></i>{{labels[user.status] || user.status}}</span></td><td><span class="origin" :class="{gift:user.status==='manual'}"><Gift v-if="user.status==='manual'" :size="13"/>{{user.status==='manual'?'Manual':user.status==='free'?'—':'Stripe'}}</span></td><td>{{view==='subscriptions'?(user.expires?date(user.expires):user.status==='manual'?'Sem vencimento':user.status==='active'?'Em andamento':'—'):date(user.joined)}}</td><td class="amount">{{user.status==='active'?'Pro pago':user.status==='manual'?'Pro gratuito':'Sem Pro'}}<small v-if="user.status==='manual'">cortesia</small></td><td><button class="icon-button" :aria-label="'Ver detalhes de '+user.name" @click="openDetails(user)"><MoreHorizontal :size="19"/></button></td></tr></tbody></table><p v-if="listLoading" class="admin-load-status" role="status">Carregando usuários…</p><div v-if="!listLoading&&!rows.length" class="empty-state"><Search :size="30"/><h3>Nenhum usuário por aqui.</h3><p>Tente outro nome, e-mail ou combinação de filtros.</p><button class="button" @click="search='';statusFilter='all';originFilter='all'">Limpar filtros</button></div></div>
      <footer class="pagination"><span>{{resultTotal}} resultados · dados do sistema</span><div><button class="button" :disabled="page<=1" @click="page--">Anterior</button><span>{{Math.min(page,totalPages)}} de {{totalPages}}</span><button class="button" :disabled="page>=totalPages" @click="page++">Próxima </button></div></footer>
     </section>
     <div class="courtesy-explainer"><Gift :size="20"/><div><strong>Um gesto de incentivo também é Pro.</strong><p>Conceda benefícios sem cobrança para parceiros, equipe ou usuários que merecem um cuidado extra. Toda concessão tem motivo e histórico.</p></div><button class="text-link" @click="openGrant()">Conceder cortesia </button></div>
    </template>
    <template v-else-if="view==='activity'"><section class="panel activity-list"><div class="panel-title"><div><h3>Histórico administrativo</h3><p>Concessões, configurações e alterações de acesso.</p></div><span class="pill sage">{{eventTotal}} eventos</span></div><div class="timeline"><div v-for="event in events" :key="event.id" class="timeline-item"><span class="timeline-icon" :class="event.type"><Gift v-if="event.type==='grant'" :size="17"/><ShieldCheck v-else :size="17"/></span><div><strong>{{event.title}}</strong><p>{{event.detail}}</p><small v-if="event.expires_at">Validade: {{dateTime(event.expires_at)}}</small><small>{{dateTime(event.time)}} · {{event.actor}}</small></div><span class="event-label">Registro</span></div></div><div v-if="!events.length" class="empty-state"><History :size="24"/><p>Nenhuma ação administrativa registrada.</p></div><footer class="pagination"><span>{{eventTotal}} registros</span><div><button class="button" :disabled="eventPage<=1" @click="eventPage--">Anterior</button><span>{{eventPage}} de {{eventPages}}</span><button class="button" :disabled="eventPage>=eventPages" @click="eventPage++">Próxima</button></div></footer></section></template>
    <template v-else-if="view==='settings'"><div class="settings-layout"><div class="settings-index"><span class="settings-selected"><Settings2 :size="16"/> Preferências gerais</span><p>Estas configurações são aplicadas ao sistema. Toda alteração fica registrada no histórico administrativo.</p><div class="settings-art"><img src="/ui/admin-growth.png" alt="Arcos verdes de vidro com plantas"/><strong>Uma boa base<br>para continuar crescendo.</strong></div></div>
     <form class="settings-form" @submit.prevent="saveSettings"><section class="panel setting-section"><div class="panel-title"><div><h3>A identidade do seu espaço</h3><p>Informações de contato da administração.</p></div></div><div class="field-grid"><label>Nome do produto<input v-model="draft.name" required maxlength="50"/></label><label>E-mail de suporte<input v-model="draft.email" type="email" placeholder="Opcional"/></label></div></section>
     <section class="panel setting-section"><div class="panel-title"><div><h3>Cortesias e cobrança</h3><p>Benefícios manuais e situação da integração Stripe.</p></div><CreditCard :size="19"/></div><div class="field-grid"><label>Período padrão de cortesia<AppSelect v-model="draft.defaultGrant" block :options='[{"label":"7 dias","value":"7"},{"label":"30 dias","value":"30"},{"label":"90 dias","value":"90"}]'/></label><div class="admin-billing-status"><small>INTEGRAÇÃO STRIPE</small><strong>{{billingConfig?.ready?'Configurada':'Configuração pendente'}}</strong><span>Moeda de referência: {{billingConfig?.currency?.toUpperCase()}}</span></div></div><div class="inline-note"><ShieldCheck :size="17"/><p>As credenciais Stripe são configuradas no ambiente do servidor. Nenhuma chave é exibida neste painel. Cortesias são benefícios separados da cobrança.</p></div></section>
     <section class="panel setting-section"><div class="panel-title"><div><h3>Comunicação e disponibilidade</h3><p>Como o Tempozi conversa com a sua base.</p></div></div><label class="toggle-row"><span><strong>Novos cadastros</strong><small>Permitir a criação de novas contas.</small></span><input v-model="draft.newAccounts" type="checkbox" role="switch"/><span class="toggle"></span></label><label class="toggle-row"><span><strong>Modo de manutenção</strong><small>Suspender o workspace dos usuários. Administração e cobrança continuam acessíveis.</small></span><input v-model="draft.maintenance" type="checkbox" role="switch"/><span class="toggle"></span></label></section><div class="settings-actions"><button type="button" class="button" @click="discardSettings">Descartar alterações</button><button class="button primary" :disabled="submitting || loading"><Check :size="16"/> {{submitting?'Salvando…':'Salvar configurações'}}</button></div></form>
    </div></template>
    <footer class="page-footer"><span class="footer-brand"><Layers3 :size="15"/> tempozi.</span><span>Feito para manter as coisas em movimento.</span><span>Administração do sistema</span></footer>
   </div></Transition>
  </main>
 </div>
 <Transition name="toast"><div v-if="toast" class="toast" role="status"><CheckCircle2 :size="20"/>{{toast}}<button aria-label="Fechar aviso" @click="toast=''"><X :size="15"/></button></div></Transition>
 <Transition name="modal"><div v-if="modal" class="modal-backdrop" @click.self="close()"><section class="modal-card" :class="{wide:modal==='grant'}" role="dialog" aria-modal="true" aria-labelledby="dialog-title">
  <button class="modal-close icon-button" aria-label="Fechar janela" :disabled="submitting" @click="close()"><X :size="20"/></button>
  <template v-if="modal==='grant'"><div class="modal-icon"><Gift :size="25"/></div><span class="eyebrow">UM INCENTIVO PARA IR ALÉM</span><h2 id="dialog-title">O próximo passo é por sua conta.</h2><p class="modal-description">Conceda acesso real ao Tempozi Pro sem gerar cobrança. Uma cortesia com propósito, prazo e transparência.</p><form @submit.prevent="grant"><div class="recipient-field"><label for="grant-recipient">Quem vai receber?</label><UserSearchSelect v-model="form.user" :users="grantTargets" remote :loading="recipientLoading" :error="recipientError" :total="recipientTotal" @search="searchRecipients"/><small>Contas desativadas e cobranças Stripe em andamento não são elegíveis.</small></div><label>Por quanto tempo?<AppSelect v-model="form.duration" block :options='[{"label":"7 dias","value":"7"},{"label":"30 dias","value":"30"},{"label":"90 dias","value":"90"},{"label":"Escolher uma data","value":"custom"},{"label":"Sem vencimento","value":"forever"}]'/></label><label v-if="form.duration==='custom'">Último dia do acesso ({{grantTimezone}})<input type="date" v-model="form.until" :min="minGrantDate" required/></label><label>Motivo da concessão<textarea v-model="form.reason" placeholder="Ex.: parceria, teste acompanhado ou benefício para a equipe." required maxlength="300" rows="3"></textarea><small>Esse motivo será registrado no histórico administrativo.</small></label><div class="grant-summary"><span class="plan-mark"><Sparkles :size="20"/></span><div><strong>Tempozi Pro · cortesia</strong><small>Todos os benefícios, sem cobrança automática.</small></div><strong>R$ 0,00</strong></div><p v-if="formError" class="error-message" role="alert">{{formError}}</p><div class="modal-actions"><button type="button" class="button" :disabled="submitting" @click="close()">Cancelar</button><button class="button primary" :disabled="submitting"><RefreshCw v-if="submitting" :size="16" class="spin"/><Gift v-else :size="16"/>{{submitting?'Concedendo…':'Confirmar cortesia'}}</button></div></form><p class="modal-footnote">A concessão não cria cobranças e fica registrada no histórico.</p></template>
  <template v-else-if="modal==='details'&&selected"><div class="detail-head"><span class="avatar large" :class="'color-'+selected.id%4">{{initials(selected.name)}}</span><span class="pill sage">USUÁRIO #{{String(selected.id).padStart(4,'0')}}</span></div><h2 id="dialog-title">{{selected.name}}</h2><p class="modal-description">{{selected.email}}</p><span class="status-badge" :class="selected.status"><i></i>{{labels[selected.status] || selected.status}}</span><div class="detail-grid"><div><small>CADASTRO</small><strong>{{dateFull(selected.joined)}}</strong></div><div><small>CONTA</small><strong>{{selected.disabled?'Desativada':'Habilitada'}}</strong></div><div><small>ORIGEM DO ACESSO</small><strong>{{selected.source==='manual'?'Concessão manual':selected.source==='stripe'?'Stripe':'Plano gratuito'}}</strong></div><div><small>{{selected.status==='manual'?'FIM DA CORTESIA':'FIM DO ACESSO'}}</small><strong>{{selected.expires?dateTime(selected.expires):selected.status==='manual'?'Sem vencimento':'—'}}</strong></div></div><div v-if="selected.stripe_status" class="inline-note"><CreditCard :size="17"/><p>Situação no Stripe: {{labels[selected.stripe_status] || selected.stripe_status}}<br><span v-if="selected.subscription_id">ID: {{selected.subscription_id}}</span></p></div><div v-if="selected.courtesy_active && selected.status==='active'" class="inline-note"><Gift :size="17"/><p>Esta conta também tem uma cortesia ativa {{selected.courtesy_expires?'até '+dateFull(selected.courtesy_expires):'sem vencimento'}}. Encerrar a cortesia preserva a assinatura paga.</p></div><div v-if="selected.reason" class="inline-note"><Gift :size="17"/><p>{{selected.reason}}</p></div><div class="detail-actions"><button v-if="selected.can_grant" class="button primary" @click="openGrant(selected)"><Gift :size="15"/>{{selected.status==='manual'?'Renovar cortesia':'Conceder Pro'}}</button><button v-if="selected.courtesy_active" class="button danger" @click="requestRevoke">Encerrar cortesia</button><div v-if="['active','past_due'].includes(selected.status)" class="inline-note">Assinatura paga: cancelamento e reembolso devem ser feitos no Stripe.</div><button v-if="!selected.is_admin" class="text-link muted" @click="toggleAccount">{{selected.disabled?'Reativar conta':'Desativar conta'}} </button></div></template>
  <template v-else-if="modal==='revoke'"><div class="modal-icon warning"><Gift :size="25"/></div><h2 id="dialog-title">Encerrar esta cortesia?</h2><p class="modal-description">{{selected?.name}} perderá o benefício manual. Os dados serão preservados. Se houver uma assinatura paga, ela continuará como está.</p><label>Motivo do encerramento<textarea v-model="actionReason" rows="3" maxlength="300" placeholder="Explique o motivo para o histórico administrativo." required/></label><p v-if="formError" class="error-message" role="alert">{{formError}}</p><div class="modal-actions"><button class="button" :disabled="submitting" @click="modal='details'">Voltar</button><button class="button danger" :disabled="submitting||actionReason.trim().length<3" @click="revoke">{{submitting?'Encerrando…':'Encerrar cortesia'}}</button></div></template>
  <template v-else-if="modal==='notifications'"><div class="modal-icon"><Bell :size="24"/></div><h2 id="dialog-title">Um pouco de atenção por aqui.</h2><p class="modal-description">Pendências atuais da sua operação.</p><p v-if="counts.pending===0" class="inline-note"><CheckCircle2 :size="18"/> Nenhum pagamento pendente registrado.</p><button v-else class="notification-card" @click="close();go('subscriptions','past_due')"><Clock3 :size="20"/><span><strong>{{counts.pending}} pagamentos pendentes</strong><small>Veja as assinaturas que precisam de acompanhamento.</small></span></button><button class="notification-card" @click="close();go('subscriptions','manual')"><Gift :size="20"/><span><strong>{{counts.manual}} acessos cortesia</strong><small>Acompanhe os benefícios concedidos manualmente.</small></span></button></template>

  <template v-else-if="modal==='account'"><div class="modal-icon warning"><ShieldCheck :size="25"/></div><h2 id="dialog-title">{{selected?.disabled?'Reativar esta conta?':'Desativar esta conta?'}}</h2><p class="modal-description">{{selected?.name}} {{selected?.disabled?'voltará a acessar o sistema.':'não poderá entrar nem continuar usando o sistema. Os dados e a cobrança Stripe serão preservados.'}}</p><label>Motivo da alteração<textarea v-model="actionReason" rows="3" maxlength="300" placeholder="Explique o motivo para o histórico administrativo." required/></label><p v-if="formError" class="error-message" role="alert">{{formError}}</p><div class="modal-actions"><button class="button" :disabled="submitting" @click="modal='details'">Voltar</button><button class="button" :class="selected?.disabled?'primary':'danger'" :disabled="submitting||actionReason.trim().length<3" @click="confirmAccount">{{submitting?'Salvando…':selected?.disabled?'Reativar conta':'Desativar conta'}}</button></div></template><template v-else><div class="modal-icon"><Sparkles :size="25"/></div><h2 id="dialog-title">Um painel para cuidar do Tempozi.</h2><p class="modal-description">Acompanhe as contas, pesquise usuários e conceda acesso Pro de cortesia. As alterações são persistidas no sistema e registradas com a identidade do administrador.</p><div class="help-steps"><div><span>01</span><p><strong>Acompanhe</strong>Usuários, receita paga e cortesias em um só lugar.</p></div><div><span>02</span><p><strong>Gerencie</strong>Filtre a base, abra os detalhes e conceda uma cortesia.</p></div><div><span>03</span><p><strong>Tenha contexto</strong>Veja cada ação no histórico e personalize as preferências.</p></div></div><button class="button primary full" @click="close()">Explorar painel </button></template>
 </section></div></Transition>
</div>
</template>
